// === Tab: mySketch ===
let sh;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	sh = createShader(vert, frag);
	shader(sh);
	sh.setUniform("u_resolution", [width * pixelDensity(), height * pixelDensity()]);

	noStroke();
}

function draw() {
	sh.setUniform("n1", 10 * noise(frameCount / 100.0));
	sh.setUniform("n2", (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/100.0);
	sh.setUniform("n3", 8 * noise(frameCount / 90.0));
	sh.setUniform("m", map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0.0, width, 0.0, 20.0));
	rect(0, 0, width, height);
}

var vert = `
precision highp float;

attribute vec3 aPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

var frag = `

precision highp float;

uniform vec2 u_resolution;

uniform float n1,n2,n3;
uniform float m;

//Because I knew nothing about vertical shaders
vec2 expandY( in vec2 pos, float ratio ){
    vec2 npos = vec2(0.0);
    pos = pos-vec2(0.5);
    npos = vec2(pos.x, ratio*pos.y);
    return vec2(0.5)-npos;
}

void main() {
    vec2 st = gl_FragCoord.xy/u_resolution;
    vec3 color = vec3(0.0);

    st = expandY(st, u_resolution.y/u_resolution.x);
    vec2 toCenter = vec2(0.5)-st;
    float angle = atan(toCenter.y,toCenter.x);
    float radius = length(toCenter)*2.0;

    float dif = pow(pow(abs(cos(m*angle/4.0)), n2) + pow(abs(sin(m*angle/4.0)),n3), -1.0/n1);
    dif *= 0.5;
    dif -= radius;
    float r = step(0.15, mod(dif,0.2));
    float g = step(0.15, mod(dif,0.21));
    float b = step(0.15, mod(dif,0.22));

    gl_FragColor = vec4(vec3(r,g,b), 1.0);
}
`;

